import itertools, sys

def is_one_in_three_sat(num_vars, clauses):
    # assignments as tuple of bools length num_vars (1-indexed)
    for vals in itertools.product([False, True], repeat=num_vars):
        ok=True
        for cl in clauses:
            true_count = sum(vals[i-1] for i in cl)
            if true_count != 1:
                ok=False
                break
        if ok:
            return True
    return False

def find_unsat(max_vars=4, max_clauses=3):
    for m in range(3, max_vars+1):
        vars_range = list(range(1,m+1))
        all_clauses = list(itertools.combinations(vars_range,3))
        # try combinations of clauses up to max_clauses
        for r in range(1, max_clauses+1):
            for combo in itertools.combinations(all_clauses, r):
                if not is_one_in_three_sat(m, combo):
                    print('Found unsat m',m,'clauses',combo)
                    return m, combo
    return None

print(find_unsat())
