import itertools, sys

def gadget_satisfiable(lits, clauses, aux_count):
    # lits: tuple of 0/1 for a,b,c
    # aux_count: number of aux vars
    # clauses: list of triples of indices, where 0=a,1=b,2=c, 3.. are aux vars
    for aux_vals in itertools.product([0,1], repeat=aux_count):
        # build full assignment list
        assign = list(lits) + list(aux_vals)
        ok = True
        for cl in clauses:
            cnt = sum(assign[i] for i in cl)
            if cnt != 1:
                ok = False
                break
        if ok:
            return True
    return False

variables = ['a','b','c']
max_aux = 2
max_clauses = 4
found = False
for aux_count in range(1, max_aux+1):
    var_indices = list(range(3+aux_count))
    all_triples = list(itertools.combinations(var_indices, 3))
    for r in range(1, max_clauses+1):
        for clause_set in itertools.combinations(all_triples, r):
            good = True
            for lits in itertools.product([0,1], repeat=3):
                sat = gadget_satisfiable(lits, clause_set, aux_count)
                cond = (lits[0] or lits[1] or lits[2])
                if sat != cond:
                    good = False
                    break
            if good:
                print('Found gadget', aux_count, 'aux, clauses:', clause_set)
                found = True
                raise SystemExit
print('none found')
